  binder.addEventListener('pointercancel', letGo);
  // the tap a drag can leave behind doesn't open a card
  binder.addEventListener('click', (e) => { if (performance.now() - swipe.ended < 400) { e.stopImmediatePropagation(); e.preventDefault(); } }, true);
  pick.addEventListener('change', () => { if (state === 'posed') applyPose('live'); select(Number(pick.value)); });

  const relayout = () => { if (state === 'seated') showPage(pageOf(sel)); };
  mqPhone.addEventListener('change', relayout);
  mqTablet.addEventListener('change', relayout);

  // ---- proof toggles ----
  t.holo.addEventListener('change', () => stage.classList.toggle('stage--holo', t.holo.checked));
  t.sleeve.addEventListener('change', () => stage.classList.toggle('stage--no-sleeve', t.sleeve.checked));
  t.explode.addEventListener('change', () => stage.classList.toggle('stage--exploded', t.explode.checked));
  t.rm.addEventListener('change', () => { stage.classList.toggle('stage--rm', t.rm.checked); applyLight(); });
  const setOpen = (on) => {
    finishTurn();
    t.open.checked = on;
    stage.classList.toggle('stage--open', on);
    document.documentElement.classList.toggle('binder-open', on);
    layout();
  };
  t.open.addEventListener('change', () => setOpen(t.open.checked));
  mqOpen.addEventListener('change', () => layout());
  t.light.addEventListener('change', () => { if (t.light.checked) homeLight(); else applyLight(); });

  // ---- start on the page that holds the selected card ----
  // (open on the homepage from the start with ?open, or on the shared mock)
  if (window.BINDER_OPEN || new URLSearchParams(location.search).has('open')) {
    stage.classList.add('stage--open');
    document.documentElement.classList.add('binder-open');
    t.open.checked = true;
  }
  pick.value = String(sel);
  showPage(pageOf(sel));
  // The other pages' art loads lazily for the first paint; once the page is
  // idle it is fetched and decoded, so the first turn to a page has nothing
  // to load or decode while the sheet swings.
  const warmArt = () => grid.querySelectorAll('.cf-art img[loading="lazy"]').forEach((img) => { img.loading = 'eager'; img.decode().catch(() => {}); });
  const warmUp = () => { warmArt(); setTimeout(() => rehearseTurn().catch(() => {}), 400); setTimeout(() => pockets.forEach(loadBack), 1500); };
  const warmLater = () => (window.requestIdleCallback ? requestIdleCallback(warmUp, { timeout: 2000 }) : setTimeout(warmUp, 600));
  if (document.readyState === 'complete') warmLater(); else window.addEventListener('load', warmLater, { once: true });
